    "aliases": [],
    "summary": "\"Models wholly within 3\" of this Model have a 5+ Invulnerable Save against Shooting Attacks.\"",
    "description": "\"Models wholly within 3\" of this Model have a 5+ Invulnerable Save against Shooting Attacks.\"",
    "source": "Wargear",
